pub fn lis(xs: List[Int]) -> List[Int] {
  let n = xs.len()
  var lens: List[Int] = []
  for _i in range(0, n) {
    lens = lens.push(0)
  }
  for i in range(0, n).reverse() {
    var best = 1
    for j in range(i + 1, n) {
      if xs.get_or(j, 0) > xs.get_or(i, 0) and lens.get_or(j, 0) + 1 > best {
        best = lens.get_or(j, 0) + 1
      }
    }
    lens = lens.set(i, best)
  }
  let max_len = lens.max().unwrap_or(0)
  var out: List[Int] = []
  var need = max_len
  var prev_idx = -1
  var prev_val = 0
  while need > 0 {
    var best_idx = -1
    var best_val = 0
    for k in range(prev_idx + 1, n) {
      let v = xs.get_or(k, 0)
      let ok_val = out.is_empty() or v > prev_val
      if ok_val and lens.get_or(k, 0) == need {
        if best_idx < 0 or v < best_val {
          best_idx = k
          best_val = v
        }
      }
    }
    out = out.push(best_val)
    prev_idx = best_idx
    prev_val = best_val
    need = need - 1
  }
  return out
}
